{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.agentic-harness.local/contracts/equity-market-price-evidence-request.v1.schema.json",
  "title": "Equity market price evidence request",
  "description": "One canonical request for provider-neutral equity market price evidence. The native provider testimony, provider binding and credential realization remain outside the capability's semantic identity.",
  "type": "object",
  "required": ["contractId", "payload"],
  "additionalProperties": false,
  "properties": {
    "contractId": {
      "const": "equity-market-price-evidence-request.v1"
    },
    "payload": {
      "type": "object",
      "required": ["nativeTestimony", "region", "providerBinding"],
      "additionalProperties": false,
      "properties": {
        "nativeTestimony": {
          "type": "object",
          "description": "The raw supplier payload. Its shape is selected by presence, never by provider identity."
        },
        "region": {
          "type": "string",
          "minLength": 1
        },
        "providerBinding": {
          "type": "object",
          "required": ["bindingId", "providerId"],
          "additionalProperties": false,
          "properties": {
            "bindingId": { "type": "string", "minLength": 1 },
            "providerId": { "type": "string", "minLength": 1 }
          }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.agentic-harness.local/contracts/equity-market-price-evidence.v1.schema.json",
  "title": "Equity market price evidence",
  "description": "One canonical outcome for provider-neutral equity market price evidence: either the resolved evidence or an explicit native-testimony rejection. An observed price is attributable provider testimony, not an assertion of intrinsic value or cross-provider equivalence.",
  "type": "object",
  "required": ["contractId", "disposition", "providerTestimony"],
  "additionalProperties": false,
  "properties": {
    "contractId": {
      "const": "equity-market-price-evidence.v1"
    },
    "disposition": {
      "enum": [
        "EQUITY_MARKET_PRICE_EVIDENCE_RESOLVED",
        "NATIVE_MARKET_PRICE_TESTIMONY_REJECTED"
      ]
    },
    "payload": {
      "type": "object",
      "required": ["symbol", "region", "currency", "observedPrice", "observedMarketTime", "marketState", "exchange", "sourceAttribution"],
      "additionalProperties": false,
      "properties": {
        "symbol": { "type": "string", "minLength": 1 },
        "region": { "type": "string", "minLength": 1 },
        "currency": { "type": "string", "minLength": 1 },
        "observedPrice": { "type": "number" },
        "observedMarketTime": { "type": "integer", "minimum": 0 },
        "marketState": { "type": "string", "minLength": 1 },
        "exchange": { "type": "string", "minLength": 1 },
        "sourceAttribution": { "type": "string", "minLength": 1 }
      }
    },
    "reasonCode": {
      "const": "REQUIRED_NATIVE_FIELDS_ABSENT"
    },
    "absentFieldCount": {
      "type": "integer",
      "minimum": 0
    },
    "providerTestimony": {
      "type": "object",
      "required": ["bindingId", "providerId", "nativeShape"],
      "additionalProperties": false,
      "properties": {
        "bindingId": { "type": "string", "minLength": 1 },
        "providerId": { "type": "string", "minLength": 1 },
        "nativeShape": {
          "enum": [
            "quoteSummary.result.0.price",
            "quoteResponse.result.0"
          ]
        }
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": { "disposition": { "const": "EQUITY_MARKET_PRICE_EVIDENCE_RESOLVED" } }
      },
      "then": {
        "required": ["payload"],
        "properties": {
          "reasonCode": false,
          "absentFieldCount": false
        }
      }
    },
    {
      "if": {
        "properties": { "disposition": { "const": "NATIVE_MARKET_PRICE_TESTIMONY_REJECTED" } }
      },
      "then": {
        "required": ["reasonCode", "absentFieldCount"],
        "properties": {
          "payload": false
        }
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.agentic-harness.local/contracts/equity-market-price-provider-unavailable.v1.schema.json",
  "title": "Equity market price provider unavailable",
  "description": "Resolution is held with attributable provider attempt evidence and no price evidence is invented.",
  "type": "object",
  "required": ["contractId", "disposition"],
  "properties": {
    "contractId": {
      "const": "equity-market-price-provider-unavailable.v1"
    },
    "disposition": {
      "const": "EQUITY_MARKET_PRICE_PROVIDER_UNAVAILABLE"
    },
    "providerAttemptEvidence": {
      "type": "object"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.agentic-harness.local/contracts/native-equity-market-price-testimony-rejection.v1.schema.json",
  "title": "Native equity market price testimony rejection",
  "description": "The native testimony is rejected without widening the mapping or emitting canonical price evidence.",
  "type": "object",
  "required": ["contractId", "disposition", "reasonCode"],
  "properties": {
    "contractId": {
      "const": "native-equity-market-price-testimony-rejection.v1"
    },
    "disposition": {
      "const": "NATIVE_MARKET_PRICE_TESTIMONY_REJECTED"
    },
    "reasonCode": {
      "const": "REQUIRED_NATIVE_FIELDS_ABSENT"
    },
    "absentFieldCount": {
      "type": "integer",
      "minimum": 0
    },
    "providerTestimony": {
      "type": "object"
    }
  }
}
